function x([o,c]){const a=Math.sin(o*Math.PI/180);return[(c+180)/360,.5-Math.log((1+a)/(1-a))/(4*Math.PI)]}function y(o,c,a,t=16){let s=1/0,n=1/0,e=-1/0,M=-1/0;for(const m of o){const[r,f]=x(m);s=Math.min(s,r),n=Math.min(n,f),e=Math.max(e,r),M=Math.max(M,f)}const u=Math.max(e-s,1e-9),l=Math.max(M-n,1e-9),h=Math.min((c-t*2)/u,(a-t*2)/l),d=(c-u*h)/2,p=(a-l*h)/2;return m=>{const[r,f]=x(m);return[d+(r-s)*h,p+(f-n)*h]}}function $(o,c,a){const t=[];for(let s=0;s<o.length;s++){const n=c(o[s]),e=t.at(-1);e&&s<o.length-1&&Math.hypot(n[0]-e[0],n[1]-e[1])<a||t.push(n)}return t}const i=o=>`${o[0].toFixed(1)} ${o[1].toFixed(1)}`;function I(o,c,a=.6){return $(o,c,a).map((t,s)=>`${s?"L":"M"}${i(t)}`).join("")}function P(o,c,a=4){const t=$(o,c,a);if(t.length<3)return t.map((n,e)=>`${e?"L":"M"}${i(n)}`).join("");let s=`M${i(t[0])}`;for(let n=1;n<t.length-1;n++){const e=[(t[n][0]+t[n+1][0])/2,(t[n][1]+t[n+1][1])/2];s+=`Q${i(t[n])} ${i(e)}`}return`${s}L${i(t[t.length-1])}`}function g(o,c){const a=Math.PI/180,t=(c[0]-o[0])*a,s=(c[1]-o[1])*a,n=Math.sin(t/2)**2+Math.cos(o[0]*a)*Math.cos(c[0]*a)*Math.sin(s/2)**2;return 2*6371*Math.asin(Math.sqrt(n))}export{P as a,g as d,y as f,x as m,I as t};
